# -*- coding: utf-8 -*-
# ---------- 5. La cadena del relato de Sayf ----------
add(5, "Qasim al-Samarrai, editor de Sayf (1997)", key="SyN", specs=["TS3"],
 title="Nota del editor: «la noticia completa no está en al-Tabari»; la conserva al-Qaysi, y «la cambió y alteró mucho»",
 ref="Sayf ibn ʿUmar, Kitab al-ridda wa-l-futuh, ed. Qasim al-Samarrai (2.ª impr., Riad: Dar Umayya, 1418/1997), p. 136, notas 3 y 4",
 ar_ref="الردة والفتوح، ص ١٣٦، الحاشيتان ٣ و٤", site="archive.org (escaneo; es el mismo PDF que islamland.com/uploads/books/35696.pdf)", url="https://archive.org/details/20220829_20220829_1712 (p. 136)",
 lang="árabe (escaneo de la edición impresa)",
 es=["3. En el margen [del manuscrito] escribió: al-Faqasi.<br>4. [[k:La noticia completa no aparece en «T» [al-Tabari]]], y la transmitió al-Qaysi en Miftah al-din wa-l-muyadala bayna l-nasara wa-l-muslimin min qawl al-anbiyaʾ wa-l-mursalin wa-l-ʿulamaʾ al-rashidin, manuscrito de la Biblioteca Nacional de Argel, n.º 1557, pp. 49–90. Dijo (pp. 51–55): «Se transmite en el quinto tomo del Diwan de Sayf ibn ʿUmar al-Tamimi lo que transmitió de Ibn Abbas, que dijo…», [[a:pero cambió y alteró mucho el texto para que encajara con su estilo de exposición]]; por eso no lo hemos comparado con nuestro texto salvo en un lugar, donde nos sirvió para completar una laguna. Y doy las gracias al colega Pieter Sjoerd van Koningsveld, de la Universidad de Leiden, que me lo indicó."],
 prueba="La nota del editor confirma dos cosas. Al-Tabari, que copió a Sayf para muchos otros relatos, no recoge este. Y la única otra copia es la de al-Qaysi, un polemista posterior, que según el editor «cambió y alteró mucho el texto».",
 ojo="La cadena del n.º 133 está impresa en el texto de la edición, sin corchetes, como mostraba el análisis que enviaste (#Sy#). La nota 3 solo dice que en el margen del manuscrito pone «al-Faqasi». Un detalle de la cita: en la 2.ª impresión (1997) el relato está en las pp. 136–139; Anthony lo cita como «vol. I, pp. 132–135», de otra impresión.")

add(5, "Murtada al-ʿAskari (m. 2007), al-Ustura al-sabaʾiyya", key="Ask", specs=["T4-05", "T4-07"],
 title="El enlace de ablibrary no es la edición de Sayf: es el libro de un autor chií que cita la misma cadena y remite a «al-Ridda… pp. 136–139, n.º 133»",
 ref="Murtada al-ʿAskari, al-Ustura al-sabaʾiyya kama tajayyalaha wa-jtalaqaha Sayf ibn ʿUmar, pp. 35 y 38",
 ar_ref="الأسطورة السبئية ص ٣٥ و٣٨", site="ablibrary.net", url="https://ablibrary.net/book_content/b/16720/35 · /38",
 es=["El tercer relato: Sayf transmitió en el libro al-Ridda wa-l-futuh, y dijo: [[k:«Nos contó al-Sari: dijo: nos contó Shuʿayb: dijo: nos contó Sayf, de ʿAtiyya, de Yazid al-Faqʿasi, de Ibn Abbas, que dijo]]: Jesús —la paz sea con él— llamó a los hijos de Israel, y le respondieron los que Dios quiso. Cuando Dios —poderoso y majestuoso— lo elevó, a la gente le agradaron sus palabras, y sus compañeros llegaron a setecientas familias. [[k:Entonces dijo Pablo —cuyo sobrenombre era Abu Shaʾul, y era el rey en aquel tiempo—]]: Matad a los cristianos. Y huyeron…",
     "Y el refugio de los creyentes de entre ellos fue la península arábiga, y alcanzaron al Profeta treinta monjes de ellos que creyeron en él. [[k:Y su semejante en esta comunidad es Ibn Sabaʾ]]. Esos eran [[k:los tres relatos de Sayf sobre lo que inventó de las noticias de los sabaʾíes]], y a continuación los estudiamos, con el permiso de Dios, en su cadena y en su texto. [Nota 1:] [[k:al-Ridda wa-l-futuh de Sayf ibn ʿUmar, pp. 136–139, n.º 133]]."],
 prueba="Uno de los enlaces del análisis (ablibrary.net, libro 16720) no es la edición de Sayf. Es un estudio del erudito chií Murtada al-ʿAskari, que copia el relato con la misma cadena. Para él, Sayf «inventó» las noticias de Ibn Sabaʾ, y el relato de Pablo es el preámbulo de esa leyenda.",
 ojo="La cita es correcta, pero es de segunda mano y de un autor con su propia polémica: al-ʿAskari quiere desacreditar a Sayf por razones internas del debate suní-chií. Para el debate, cita la edición impresa (#Sy#, #SyN#) y usa a al-ʿAskari solo como apoyo.")

add(5, "al-Tabari (m. 310 H), Tarij", key="TbS", specs=["T4-08"],
 title="La misma cadena —Sayf, de ʿAtiyya, de Yazid al-Faqʿasi— es la del relato de Ibn Sabaʾ en al-Tabari: «ʿAbd Allah ibn Sabaʾ era un judío de Saná»",
 ref="al-Tabari, Tarij al-rusul wa-l-muluk (Dar al-Turath, Beirut 1387 H), vol. 4, p. 340 (año 35 H)",
 ar_ref="تاريخ الطبري ٤/٣٤٠", site=SH, url=S + "9783/2229",
 es=["…según lo que me escribió al-Sari, de Shuʿayb, [[k:de Sayf, de ʿAtiyya, de Yazid al-Faqʿasi, que dijo]]: [[k:ʿAbd Allah ibn Sabaʾ era un judío de la gente de Saná]], de madre negra; se hizo musulmán en tiempos de ʿUthman, luego anduvo por los países de los musulmanes intentando extraviarlos; empezó por el Hiyaz, luego Basora, luego Kufa, luego Siria…"],
 prueba="Es la misma cadena de Sayf, pero para el relato de Ibn Sabaʾ, el judío que según Sayf corrompió el islam. En la edición de al-Samarrai, este relato es el n.º 134 y va justo después del de Pablo, que termina diciendo: «y su semejante en esta comunidad es Ibn Sabaʾ».",
 ojo="Aquí la cadena termina en Yazid al-Faqʿasi, sin Ibn Abbas. En el relato de Pablo la misma cadena llega hasta Ibn Abbas (m. 68 H), un siglo antes de Sayf. Los dos relatos son un par: un judío corrompe el cristianismo y otro judío corrompe el islam.")

add(5, "Ibn Abi Hatim (m. 327 H / 938)", key="Jr", specs=["T4-09"],
 title="Ibn Maʿin: «débil en el hadiz»; Abu Hatim: «abandonado en el hadiz; su hadiz se parece al de al-Waqidi»",
 ref="Ibn Abi Hatim, al-Yarh wa-l-taʿdil (Hyderabad, 1371/1952), vol. 4, p. 278, n.º 1198",
 ar_ref="الجرح والتعديل ٤/٢٧٨، رقم ١١٩٨", site=SH, url=S + "2170/1862",
 es=["1198 — Sayf ibn ʿUmar al-Dabbi: transmitió de ʿUbayd Allah ibn ʿUmar al-ʿUmari; transmitieron de él ʿAbd al-Rahman ibn Muhammad al-Muharibi y al-Nadr ibn Hammad; se lo oí decir a mi padre. Nos contó ʿAbd al-Rahman: se leyó ante al-ʿAbbas ibn Muhammad al-Duri, [[k:de Yahya ibn Maʿin, que dijo: Sayf ibn ʿUmar al-Dabbi, del que transmite al-Muharibi, es débil en el hadiz]]. Nos contó ʿAbd al-Rahman: se le preguntó a mi padre por Sayf ibn ʿUmar al-Dabbi, [[k:y dijo: abandonado en el hadiz; su hadiz se parece al de al-Waqidi]]."],
 prueba="Confirma dos de las calificaciones del análisis: Ibn Maʿin, «débil en el hadiz» (daʿif al-hadith), y Abu Hatim, «abandonado en el hadiz» (matruk al-hadith), uno de los grados más bajos.",
 ojo="El análisis omite el final de la frase de Abu Hatim: «su hadiz se parece al de al-Waqidi». Es decir, lo juzga como un historiador que recoge noticias, no como un transmisor fiable de hadices. Eso refuerza el punto: para la historia antigua es material sin garantía.")

add(5, "Ibn Hibban (m. 354 H / 965)", key="Mj", specs=["T4-10", "T4-11"],
 title="Ibn Hibban: «acusado de zandaqa»… «transmite lo inventado atribuyéndolo a los fiables»; Ibn Numayr: «Sayf inventaba hadices»",
 ref="Ibn Hibban, al-Mayruhin, ed. Mahmud Ibrahim Zayid (Alepo: Dar al-Waʿy, 1396 H), vol. 1, pp. 345–346",
 ar_ref="المجروحين لابن حبان ١/٣٤٥–٣٤٦", site=SH, url=S + "5834/246 · 5834/247",
 es=["Sayf ibn ʿUmar al-Dabbi al-Usaydi, de la gente de Basora; [[k:acusado de zandaqa [herejía encubierta]]]; transmite de ʿUbayd Allah ibn ʿUmar; transmitieron de él al-Muharibi y los de Basora; era originario de Kufa; [[k:transmite lo inventado atribuyéndolo a transmisores fiables]]. Nos contó Muhammad ibn ʿAbd Allah ibn ʿAbd al-Salam en Beirut: oí a Yaʿfar ibn Aban decir: oí…",
     "…a Ibn Numayr decir: Sayf al-Dabbi es tamimí, y Yamiʿ decía: me contó un hombre de los Banu Tamim. [[k:Y Sayf inventaba hadices]], [[k:y había sido acusado de zandaqa]]."],
 prueba="Confirma las otras dos calificaciones del análisis, con las palabras exactas de Ibn Hibban: «acusado de zandaqa» y «transmite lo inventado atribuyéndolo a los fiables». Y añade el juicio de Ibn Numayr: «inventaba hadices».",
 ojo="Ibn Hayar dice que Ibn Hibban «se excedió» al hablar de Sayf (#Tq#). Para ser justos, conviene citar también la calificación más moderada de Ibn Hayar.")

add(5, "Ibn ʿAdi (m. 365 H / 976)", key="Kml", specs=["T4-16", "T4-17"],
 title="Ibn ʿAdi: Ibn Maʿin, «una moneda de cobre vale más que él»; «la mayoría de sus hadices son rechazables… está más cerca de la debilidad que de la veracidad»",
 ref="Ibn ʿAdi, al-Kamil fi duʿafaʾ al-riyal, ed. ʿAdil Ahmad ʿAbd al-Mawyud y ʿAli Muhammad Muʿawwad (Dar al-Kutub al-ʿIlmiyya), vol. 4, pp. 507–508, n.º 851",
 ar_ref="الكامل لابن عدي ٤/٥٠٧–٥٠٨، رقم ٨٥١", site=SH, url=S + "12579/2083 · 12579/2084",
 es=["851 — Sayf ibn ʿUmar al-Dabbi, de Kufa. Oí a Ibn Hammad decir: nos contó al-ʿAbbas, de Yahya, [[k:que dijo: Sayf ibn ʿUmar al-Dabbi es débil.]] Y oí a Nuʿaym ibn ʿAbd al-Malik decir: oí a Abu Yaʿfar al-Hadrami decir: oí a Yahya ibn Maʿin, cuando le preguntaron por Sayf ibn ʿUmar, [[k:y dijo: una moneda de cobre vale más que él.]]",
     "Dijo el shayj [Ibn ʿAdi]: Y Sayf ibn ʿUmar tiene otros hadices además de los que he mencionado; algunos son conocidos, [[k:pero la mayoría son rechazables y nadie los corrobora]], [[k:y está más cerca de la debilidad que de la veracidad]]."],
 prueba="El gran catálogo de transmisores débiles confirma el consenso: la mayoría de lo que transmite Sayf es «rechazable» y «nadie lo corrobora». Es justo el caso del relato de Pablo, que solo está en Sayf.",
 ojo="Ninguno contra el punto.")

add(5, "al-Dahabi (m. 748 H / 1348)", key="Mzn", specs=["T4-12"],
 title="al-Dahabi: «autor de las Conquistas y la Apostasía… es como al-Waqidi… era un historiador entendido»; y resume a los críticos",
 ref="al-Dahabi, Mizan al-iʿtidal, ed. ʿAli Muhammad al-Biyawi (Dar al-Maʿrifa, 1382/1963), vol. 2, p. 255, n.º 3637",
 ar_ref="ميزان الاعتدال ٢/٢٥٥، رقم ٣٦٣٧", site=SH, url=S + "1692/922",
 es=["3637 — Sayf ibn ʿUmar al-Dabbi al-Usaydi; se le llama también al-Tamimi al-Buryumi y al-Saʿdi al-Kufi. [[k:Autor de las Conquistas y la Apostasía y de otras cosas. Es como al-Waqidi.]] Transmite de Hisham ibn ʿUrwa, de ʿUbayd Allah ibn ʿUmar, de Yabir al-Yuʿfi y de muchísimos desconocidos. [[k:Era un historiador entendido.]] Transmitieron de él Yabbara ibn al-Mugallis, Abu Maʿmar al-Qatiʿi, al-Nadr ibn Hammad al-ʿAtaki y otros. [[k:Dijo ʿAbbas, de Yahya: débil.]] Y transmitió Mutayyan, de Yahya: una moneda de cobre vale más que él. Dijo Abu Dawud: no es nada. [[k:Dijo Abu Hatim: abandonado.]] [[k:Dijo Ibn Hibban: acusado de zandaqa.]] Dijo Ibn ʿAdi: la mayoría de su hadiz es rechazable."],
 prueba="Al-Dahabi identifica a este Sayf con el autor del Kitab al-ridda wa-l-futuh, el libro donde está el relato de Pablo. Y resume en pocas líneas todos los juicios negativos.",
 ojo="Al-Dahabi también dice que «era un historiador entendido» y que transmite «de muchísimos desconocidos». Su valor está en las crónicas de batallas, no en relatos sobre el siglo I que pone en boca de Ibn Abbas.")

add(5, "Ibn Hayar al-ʿAsqalani (m. 852 H / 1449)", key="Tq", specs=["T4-13", "T4-15"],
 title="Ibn Hayar: «débil en el hadiz, referencia en la historia; Ibn Hibban se excedió con él»; al-Hakim: «acusado de zandaqa, y en la transmisión no vale nada»",
 ref="Ibn Hayar, Taqrib al-Tahdhib, ed. Muhammad ʿAwwama (Alepo: Dar al-Rashid, 1406/1986), p. 262, n.º 2724; Tahdhib al-Tahdhib (Hyderabad, 1326 H), vol. 4, p. 296",
 ar_ref="تقريب التهذيب ص ٢٦٢، رقم ٢٧٢٤؛ تهذيب التهذيب ٤/٢٩٦", site=SH, url=S + "8609/188 · 3310/1751",
 es=["2724 — Sayf ibn ʿUmar al-Tamimi, [[k:autor del Libro de la Apostasía]]; se le llama también al-Dabbi y otras cosas; de Kufa; [[k:débil [en el] hadiz, referencia en la historia]]; [[a:Ibn Hibban se excedió al hablar de él]]; de la octava generación; murió en tiempos de al-Rashid.",
     "…y al-Daraqutni: débil. Y dijo Ibn ʿAdi: algunos de sus hadices son conocidos, y la mayoría son rechazables, nadie los corrobora. [[k:Y dijo Ibn Hibban: transmite lo inventado atribuyéndolo a los fiables]]. Dijo: y dijeron que inventaba hadices. Digo: [[k:el resto de las palabras de Ibn Hibban: acusado de zandaqa]]. Y dijo al-Barqani, de al-Daraqutni: abandonado. [[k:Y dijo al-Hakim: acusado de zandaqa, y en la transmisión no vale nada]]."],
 prueba="El juicio final de la ciencia del hadiz: «débil en el hadiz, referencia en la historia». Ibn Hayar confirma también las palabras de Ibn Hibban y añade la de al-Hakim: «en la transmisión no vale nada».",
 ojo="Es la valoración más moderada: Sayf sirve como historiador (de las conquistas), y Ibn Hayar piensa que Ibn Hibban exageró (en azul). Pero un relato sobre el siglo I atribuido a Ibn Abbas es justamente «transmisión», donde Sayf «no vale nada».")

add(5, "Shane O. Folks (tesis doctoral, 2024), sobre S. W. Anthony", key="Fk", specs=["P-FK"], lang="inglés (páginas de la tesis, acceso abierto)",
 trnote="Traducción propia del inglés. ",
 title="Anthony: Sayf se inspiró en un relato judío anticristiano (Toledot Yeshu); Folks: la «trinidad» de padre, madre e hijo «refleja el Corán, no la Biblia»",
 ref="Shane Orin Folks, A Critique of the Early Islamic Charge That Paul Corrupted Christ's Original Religion (tesis doctoral, Southern Baptist Theological Seminary, 2024), pp. 25 y 35, resumiendo a S. W. Anthony, Der Islam 85 (2009/2010), pp. 164–202",
 ar_ref="Folks 2024, pp. 25, 35", site="repository.sbts.edu (PDF de acceso abierto)", url="https://repository.sbts.edu/bitstreams/438fd777-1c8e-4b77-ba4d-8bd9d37854e4/download",
 es=["Examinado el contexto del relato de Sayf, paso al relato mismo. [[k:Sayf afirma que la historia de la corrupción paulina le llegó de Ibn Abbas]] (m. c. 686), un famoso sabio de la primera generación de musulmanes, primo paterno de Muhammad. […] Quizá Sayf atribuye su relato a Ibn Abbas para darle más legitimidad, [[k:pero no se puede verificar una conexión directa.]] Aunque Sayf atribuye su relato de la corrupción paulina a Ibn Abbas, parece haberse inspirado [[k:en el relato judío más antiguo que se conserva sobre la corrupción cristiana]], una obra anticristiana conocida como la Vida de Jesús [Toledot Yeshu].",
     "[Nota 15:] Anthony sostiene que el conocimiento que Sayf tenía de las fuentes cristianas [[k:no era suficiente para considerarlo el inventor de la historia de la corrupción paulina]]. Por tanto, [[k:la Vida de Jesús tuvo que escribirse antes de Sayf]]. Véase Anthony, «Composition of Sayf», 194–95.",
     "En respuesta a la enseñanza de Pablo sobre la encarnación, escribe Sayf, uno de los cuatro anuncia que Jesús es el «hijo de Alá», y otro afirma que Jesús es [[k:«el tercero de tres: ¡Jesús es el Hijo, su Padre y su Madre!»]]. La formulación de la Trinidad en el relato de Sayf [[k:refleja una descripción coránica, no bíblica, de la Trinidad (Corán 5:116; 4:171)]]. Que Sayf incluya las mismas tres figuras que el Corán indica que quería culpar a Pablo no de crear la doctrina cristiana de la Trinidad, sino [[k:de la doctrina tal como la entendían los musulmanes a partir del Corán.]]"],
 prueba="Resume el estudio de Sean W. Anthony citado en el análisis, cuyo texto completo es de pago. Según Folks, Anthony relaciona la historia de Pablo con un relato judío anticristiano, el Toledot Yeshu, en el que un judío se infiltra entre los cristianos para desviarlos. Y Folks concluye que la «trinidad» de padre, madre e hijo sale del Corán, no de los cristianos.",
 ojo="Es de segunda mano: no hemos podido leer el artículo de Anthony. Su resumen publicado (recogido en la base OpenAlex) dice que Sayf compuso el relato con «una mezcla de fuentes (coránicas, exegéticas e incluso judías)», como preámbulo de su relato de Ibn Sabaʾ. Folks es un autor cristiano (tesis de un seminario bautista).")
